# main.py - runs ON THE BOARD (Nano 33 BLE Sense Rev2, MicroPython)
# Do NOT edit this file. It waits for a one-letter command from the PC
# and replies with ONE line. The sensor is only read when a command arrives.
#
#   PC sends "T"  -> board replies "DATA,TEMP,23.45"
#   PC sends "H"  -> board replies "DATA,HUM,41.20"
#   PC sends "PING" -> board replies "DATA,PONG,0"

import sys
from hs3003 import HS3003

sensor = HS3003()          # create the sensor object once at boot

while True:
    # Block here until the PC sends a line (ends with a newline)
    cmd = sys.stdin.readline().strip().upper()

    if cmd == "T":
        # Read inside the branch, only when requested
        print("DATA,TEMP,{:.2f}".format(sensor.temperature()))
    elif cmd == "H":
        print("DATA,HUM,{:.2f}".format(sensor.humidity()))
    elif cmd == "PING":
        print("DATA,PONG,0")   # lets the PC check the board is alive
